commands.command:
set -eu
case "$NODE_NAME" in
  node1) peers='node2 node3' ;;
  node2) peers='node1 node3' ;;
  node3) peers='node1 node2' ;;
  *) exit 64 ;;
esac
printf 'source=%s\n' "$NODE_NAME"
for peer in $peers; do
  printf 'target=%s ' "$peer"
  runuser -u clusterops -- ssh -o BatchMode=yes -o StrictHostKeyChecking=yes "$peer" 'printf "remote_host=%s remote_user=%s observed_source=%s\n" "$(hostname)" "$(id -un)" "$(printf "%s\n" "$SSH_CONNECTION" | awk "{print \$1}")"'
done

